"use client";

import React, { useState } from "react";
import { ShieldAlert, MapPin, Wind, Flame, Clock, HeartPulse, Home, Compass } from "lucide-react";
import { LocateMeButton } from "./LocateMeButton";

interface PersonalRiskProps {
  currentLat: number;
  currentLon: number;
  isCustomLocation: boolean;
  riskScore: number;
  riskState: string;
  nearestFireDist: number | null;
  etaMinutes: number | null;
  windSpeedKmh: number;
  windDirectionDeg: number;
}

export function PersonalRisk({
  currentLat,
  currentLon,
  isCustomLocation,
  riskScore,
  riskState,
  nearestFireDist,
  etaMinutes,
  windSpeedKmh,
  windDirectionDeg,
}: PersonalRiskProps) {
  const getRiskDetails = () => {
    if (riskScore >= 70) {
      return {
        level: "CRITICAL RISK",
        color: "text-red-400",
        badge: "bg-red-500/20 text-red-300 border-red-500/40",
        prediction: "Dense agricultural smoke plume is moving directly toward your sector.",
        actions: [
          "Close all doors and windows to minimize particulate infiltration.",
          "Postpone outdoor physical training, sports, and unnecessary travel.",
          "Use N95 or multi-layered masks if required to step outdoors.",
          "Keep vulnerable family members (asthma, elderly) in well-sealed rooms."
        ]
      };
    }
    if (riskScore >= 40) {
      return {
        level: "MODERATE RISK",
        color: "text-amber-400",
        badge: "bg-amber-500/20 text-amber-300 border-amber-500/40",
        prediction: "Smoke dispersion cone is in proximity. Changing wind vectors may affect you.",
        actions: [
          "Monitor live map updates for wind direction shifts.",
          "Ensure ventilation filters are clean and sealed.",
          "Limit prolonged outdoor exposure for children and sensitive individuals."
        ]
      };
    }
    return {
      level: "LOW RISK / NOMINAL",
      color: "text-emerald-400",
      badge: "bg-emerald-500/20 text-emerald-300 border-emerald-500/40",
      prediction: "No active combustion plumes currently threatening your coordinates.",
      actions: [
        "Atmospheric air conditions remain normal.",
        "Report any unusual smoke sightings using the Citizen Report tool.",
        "Routine agricultural activity monitored within safety margins."
      ]
    };
  };

  const details = getRiskDetails();

  return (
    <div className="w-full space-y-4">
      {/* Header */}
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-md flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <div className="p-2 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-400">
              <Compass className="w-5 h-5" />
            </div>
            <h2 className="text-xl font-black tracking-tight text-white uppercase">
              Location Risk Assessment
            </h2>
          </div>
          <p className="text-xs text-slate-400">
            Real-time personalized smoke exposure assessment tailored to your exact GPS coordinates.
          </p>
        </div>

        <div className="flex items-center gap-2">
          <LocateMeButton />
        </div>
      </div>

      {/* Main Risk Card */}
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-md space-y-6">
        <div className="flex flex-col md:flex-row md:items-center justify-between gap-4 border-b border-slate-800 pb-5">
          <div>
            <div className="flex items-center gap-2 mb-1.5">
              <span className={`text-xs font-black uppercase px-2.5 py-0.5 rounded-full border ${details.badge}`}>
                {details.level}
              </span>
              <span className="text-xs text-slate-400 font-mono">
                {currentLat.toFixed(4)}, {currentLon.toFixed(4)}
              </span>
            </div>
            <h3 className="text-lg font-extrabold text-white">
              {isCustomLocation ? "Assessed for Your Current Coordinates" : "Assessed for Keeladi Heritage Buffer Zone"}
            </h3>
            <p className="text-xs text-slate-300 mt-1 leading-relaxed">
              {details.prediction}
            </p>
          </div>

          <div className="flex items-center gap-4 bg-slate-950 p-4 rounded-xl border border-slate-800 shrink-0">
            <div className="text-center">
              <span className="text-[10px] uppercase font-bold text-slate-400">Exposure Score</span>
              <p className={`text-2xl font-black ${details.color}`}>{riskScore}/100</p>
            </div>
            <div className="h-8 w-px bg-slate-800" />
            <div className="text-center">
              <span className="text-[10px] uppercase font-bold text-slate-400">Arrival ETA</span>
              <p className="text-2xl font-black text-slate-100 font-mono">
                {etaMinutes ? `~${etaMinutes}m` : "None"}
              </p>
            </div>
          </div>
        </div>

        {/* Telemetry Breakdown */}
        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 text-xs">
          <div className="p-3 rounded-xl bg-slate-950 border border-slate-800">
            <span className="text-[10px] uppercase font-bold text-slate-400">Nearest Fire</span>
            <p className="font-mono font-bold text-slate-200 mt-1 text-sm">
              {nearestFireDist ? `${nearestFireDist.toFixed(1)} km` : "No Fire"}
            </p>
          </div>

          <div className="p-3 rounded-xl bg-slate-950 border border-slate-800">
            <span className="text-[10px] uppercase font-bold text-slate-400">Local Wind</span>
            <p className="font-mono font-bold text-emerald-400 mt-1 text-sm">
              {Math.round(windSpeedKmh)} km/h
            </p>
          </div>

          <div className="p-3 rounded-xl bg-slate-950 border border-slate-800">
            <span className="text-[10px] uppercase font-bold text-slate-400">Drift Trajectory</span>
            <p className="font-mono font-bold text-sky-400 mt-1 text-sm">
              {etaMinutes ? "Direct Corridor" : "Dispersing Away"}
            </p>
          </div>

          <div className="p-3 rounded-xl bg-slate-950 border border-slate-800">
            <span className="text-[10px] uppercase font-bold text-slate-400">Alert Status</span>
            <p className="font-mono font-bold text-amber-400 mt-1 text-sm">
              {riskState}
            </p>
          </div>
        </div>

        {/* What Should You Do? */}
        <div className="space-y-3 pt-2">
          <h4 className="text-xs font-bold uppercase tracking-wider text-slate-300 flex items-center gap-2">
            <HeartPulse className="w-4 h-4 text-emerald-400" />
            What Should You Do? (Informational Protective Guidance)
          </h4>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-2 text-xs">
            {details.actions.map((act, idx) => (
              <div
                key={idx}
                className="p-3 rounded-xl bg-slate-950 border border-slate-800 flex items-start gap-2.5 text-slate-300"
              >
                <div className="w-1.5 h-1.5 rounded-full bg-emerald-400 mt-1.5 shrink-0" />
                <span className="leading-snug">{act}</span>
              </div>
            ))}
          </div>
          <p className="text-[11px] text-slate-400 pt-1">
            * This guidance is informational and based on ambient particulate risk forecasting. Follow official district public health advisories during extreme fire emergencies.
          </p>
        </div>
      </div>
    </div>
  );
}
