"use client";

import React, { useState } from "react";
import { Bell, AlertTriangle, ShieldCheck, CheckCircle2, MapPin, Wind, Clock, Filter, Eye } from "lucide-react";

export interface AlertCardItem {
  id: string;
  severity: "CRITICAL" | "HIGH" | "MODERATE" | "LOW";
  title: string;
  location: string;
  fireSource: string;
  distanceKm: number;
  windSpeedKmh: number;
  windDirectionLabel: string;
  etaMinutes: number | null;
  createdTime: string;
  status: "ACTIVE" | "ACKNOWLEDGED" | "RESOLVED";
  signals: {
    satelliteConfirmed: boolean;
    citizenConfirmed: boolean;
    coneAligned: boolean;
  };
}

interface AlertCenterProps {
  alerts: AlertCardItem[];
  onViewOnMap?: (alert: AlertCardItem) => void;
}

export function AlertCenter({ alerts, onViewOnMap }: AlertCenterProps) {
  const [filter, setFilter] = useState<string>("ALL");
  const [alertList, setAlertList] = useState<AlertCardItem[]>(alerts);

  const filterOptions = ["ALL", "CRITICAL", "HIGH", "MODERATE", "RESOLVED"];

  const filteredAlerts = alertList.filter((a) => {
    if (filter === "ALL") return true;
    if (filter === "RESOLVED") return a.status === "RESOLVED";
    return a.severity === filter && a.status !== "RESOLVED";
  });

  const acknowledgeAlert = (id: string) => {
    setAlertList((prev) =>
      prev.map((a) => (a.id === id ? { ...a, status: "ACKNOWLEDGED" as const } : a))
    );
  };

  const getSeverityStyle = (sev: string) => {
    switch (sev) {
      case "CRITICAL":
        return {
          badge: "bg-red-500/20 text-red-400 border-red-500/40",
          border: "border-red-500/40 bg-red-950/10",
          iconColor: "text-red-400",
        };
      case "HIGH":
        return {
          badge: "bg-orange-500/20 text-orange-400 border-orange-500/40",
          border: "border-orange-500/40 bg-orange-950/10",
          iconColor: "text-orange-400",
        };
      case "MODERATE":
        return {
          badge: "bg-amber-500/20 text-amber-300 border-amber-500/40",
          border: "border-amber-500/30 bg-amber-950/10",
          iconColor: "text-amber-400",
        };
      default:
        return {
          badge: "bg-emerald-500/20 text-emerald-400 border-emerald-500/40",
          border: "border-slate-800 bg-slate-900",
          iconColor: "text-emerald-400",
        };
    }
  };

  return (
    <div className="w-full space-y-4">
      {/* Header & Filter */}
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-md flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <div className="p-2 rounded-xl bg-red-500/10 border border-red-500/30 text-red-400">
              <Bell className="w-5 h-5" />
            </div>
            <h2 className="text-xl font-black tracking-tight text-white uppercase">
              Early Warning Alert Center
            </h2>
          </div>
          <p className="text-xs text-slate-400">
            Real-time critical, high, and moderate smoke drift alerts generated for heritage sites and communities.
          </p>
        </div>

        {/* Filters */}
        <div className="flex flex-wrap gap-1.5">
          {filterOptions.map((opt) => (
            <button
              key={opt}
              onClick={() => setFilter(opt)}
              className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border ${
                filter === opt
                  ? "bg-slate-100 text-slate-900 border-white shadow-sm font-bold"
                  : "bg-slate-950 text-slate-400 border-slate-800 hover:text-white"
              }`}
            >
              {opt}
            </button>
          ))}
        </div>
      </div>

      {/* Alert Cards Grid */}
      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {filteredAlerts.length === 0 ? (
          <div className="col-span-full py-12 text-center bg-slate-900 border border-slate-800 rounded-2xl">
            <CheckCircle2 className="w-8 h-8 text-emerald-400 mx-auto mb-2" />
            <p className="text-sm font-bold text-white">No active alerts matching filter</p>
            <p className="text-xs text-slate-400">Current atmospheric dispersal corridors remain nominal.</p>
          </div>
        ) : (
          filteredAlerts.map((alert) => {
            const style = getSeverityStyle(alert.severity);
            return (
              <div
                key={alert.id}
                className={`p-5 rounded-2xl border transition-all flex flex-col justify-between space-y-4 shadow-sm ${style.border}`}
              >
                <div>
                  <div className="flex items-center justify-between gap-2 mb-2">
                    <span className={`text-[10px] font-extrabold uppercase px-2 py-0.5 rounded-full border ${style.badge}`}>
                      {alert.severity}
                    </span>
                    <span className="text-[11px] text-slate-400 font-mono">
                      {alert.createdTime}
                    </span>
                  </div>

                  <h3 className="text-base font-extrabold text-white tracking-tight mb-1">
                    {alert.title}
                  </h3>
                  <p className="text-xs text-slate-300 flex items-center gap-1.5">
                    <MapPin className="w-3.5 h-3.5 text-slate-400 shrink-0" />
                    Target: {alert.location}
                  </p>
                </div>

                {/* Telemetry metrics */}
                <div className="grid grid-cols-3 gap-2 text-xs">
                  <div className="p-2 rounded-lg bg-slate-950 border border-slate-800">
                    <span className="text-[10px] uppercase font-bold text-slate-400">Distance</span>
                    <p className="font-mono font-bold text-slate-200 mt-0.5">
                      {alert.distanceKm.toFixed(1)} km
                    </p>
                  </div>
                  <div className="p-2 rounded-lg bg-slate-950 border border-slate-800">
                    <span className="text-[10px] uppercase font-bold text-slate-400">Smoke ETA</span>
                    <p className={`font-mono font-extrabold mt-0.5 ${style.iconColor}`}>
                      {alert.etaMinutes ? `~${alert.etaMinutes} min` : "Imminent"}
                    </p>
                  </div>
                  <div className="p-2 rounded-lg bg-slate-950 border border-slate-800">
                    <span className="text-[10px] uppercase font-bold text-slate-400">Wind</span>
                    <p className="font-mono font-bold text-slate-200 mt-0.5">
                      {alert.windSpeedKmh}k {alert.windDirectionLabel}
                    </p>
                  </div>
                </div>

                {/* Evidence Signals Checklist */}
                <div className="flex items-center gap-3 text-[11px] text-slate-400 pt-1 border-t border-slate-800/80">
                  <span className="flex items-center gap-1 text-slate-300">
                    <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                    Satellite Validated
                  </span>
                  {alert.signals.citizenConfirmed && (
                    <span className="flex items-center gap-1 text-purple-300">
                      <CheckCircle2 className="w-3.5 h-3.5 text-purple-400" />
                      Citizen Corroborated
                    </span>
                  )}
                  <span className="flex items-center gap-1 text-slate-300">
                    <CheckCircle2 className="w-3.5 h-3.5 text-emerald-400" />
                    In Drift Cone
                  </span>
                </div>

                {/* Action Buttons */}
                <div className="flex items-center gap-2 pt-2">
                  {onViewOnMap && (
                    <button
                      onClick={() => onViewOnMap(alert)}
                      className="flex-1 py-2 px-3 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-bold border border-slate-700 transition-all flex items-center justify-center gap-1.5"
                    >
                      <Eye className="w-3.5 h-3.5 text-emerald-400" />
                      <span>View on Map</span>
                    </button>
                  )}
                  {alert.status !== "ACKNOWLEDGED" && alert.status !== "RESOLVED" && (
                    <button
                      onClick={() => acknowledgeAlert(alert.id)}
                      className="py-2 px-3 rounded-xl bg-slate-950 hover:bg-slate-800 border border-slate-800 text-slate-400 hover:text-white text-xs font-semibold transition-all"
                    >
                      Acknowledge
                    </button>
                  )}
                </div>
              </div>
            );
          })
        )}
      </div>
    </div>
  );
}
