"use client";

import React, { useState } from "react";
import { Shield, MapPin, AlertTriangle, CheckCircle2, ChevronRight, School, Building2, Trees } from "lucide-react";
import { PROTECTED_AREAS, ProtectedArea } from "../lib/protected-areas";
import { calculateDistance, calculateDriftRisk } from "../lib/drift";

interface ProtectedAreasProps {
  windSpeedKmh: number;
  windDirectionDeg: number;
  fires: Array<{ latitude: number; longitude: number }>;
  onSelectAreaOnMap?: (lat: number, lon: number) => void;
}

export function ProtectedAreas({
  windSpeedKmh,
  windDirectionDeg,
  fires,
  onSelectAreaOnMap,
}: ProtectedAreasProps) {
  const [selectedCategory, setSelectedCategory] = useState<string>("ALL");

  const categories = ["ALL", "Heritage / Excavation", "School / College", "Hospital", "Wildlife Sanctuary"];

  const filteredAreas = selectedCategory === "ALL"
    ? PROTECTED_AREAS
    : PROTECTED_AREAS.filter(a => a.category === selectedCategory);

  // Compute live threat analysis for each area
  const evaluatedAreas = filteredAreas.map(area => {
    let nearestFireDist = Infinity;
    let minEta: number | null = null;
    let isThreatened = false;

    for (const fire of fires) {
      const dist = calculateDistance(fire.latitude, fire.longitude, area.latitude, area.longitude);
      if (dist < nearestFireDist) nearestFireDist = dist;

      const drift = calculateDriftRisk(fire.latitude, fire.longitude, area.latitude, area.longitude, windDirectionDeg, windSpeedKmh);
      if (drift.isWithinDriftCone) {
        isThreatened = true;
        if (drift.estimatedArrivalMinutes !== null) {
          if (minEta === null || drift.estimatedArrivalMinutes < minEta) {
            minEta = drift.estimatedArrivalMinutes;
          }
        }
      }
    }

    return {
      ...area,
      nearestFireDist: nearestFireDist === Infinity ? null : nearestFireDist,
      isThreatened,
      minEta,
    };
  });

  const getCategoryIcon = (category: string) => {
    switch (category) {
      case "School / College":
        return <School className="w-4 h-4 text-sky-400" />;
      case "Hospital":
        return <Building2 className="w-4 h-4 text-rose-400" />;
      case "Wildlife Sanctuary":
        return <Trees className="w-4 h-4 text-emerald-400" />;
      default:
        return <Shield className="w-4 h-4 text-amber-400" />;
    }
  };

  return (
    <div className="w-full space-y-4">
      {/* Header & Filter */}
      <div className="bg-slate-900 border border-slate-800 rounded-2xl p-6 shadow-md flex flex-col sm:flex-row sm:items-center justify-between gap-4">
        <div>
          <div className="flex items-center gap-2 mb-1">
            <div className="p-2 rounded-xl bg-emerald-500/10 border border-emerald-500/30 text-emerald-400">
              <Shield className="w-5 h-5" />
            </div>
            <h2 className="text-xl font-black tracking-tight text-white uppercase">
              Protected Sensitive Receptors
            </h2>
          </div>
          <p className="text-xs text-slate-400">
            Real-time smoke vulnerability catalog: Archaeological excavations, community schools, hospitals, and natural reserves.
          </p>
        </div>

        {/* Filter Pills */}
        <div className="flex flex-wrap gap-1.5">
          {categories.map((cat) => (
            <button
              key={cat}
              onClick={() => setSelectedCategory(cat)}
              className={`px-3 py-1.5 rounded-lg text-xs font-semibold transition-all border ${
                selectedCategory === cat
                  ? "bg-emerald-500/20 text-emerald-300 border-emerald-500/40"
                  : "bg-slate-950 text-slate-400 border-slate-800 hover:text-white"
              }`}
            >
              {cat === "ALL" ? "All Locations" : cat}
            </button>
          ))}
        </div>
      </div>

      {/* Cards List */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {evaluatedAreas.map((area) => (
          <div
            key={area.id}
            className={`p-5 rounded-2xl border transition-all flex flex-col justify-between space-y-4 shadow-sm ${
              area.isThreatened
                ? "bg-slate-900 border-red-500/50 shadow-red-950/20"
                : "bg-slate-900 border-slate-800 hover:border-slate-700"
            }`}
          >
            <div>
              <div className="flex items-center justify-between gap-2 mb-2">
                <span className="flex items-center gap-1.5 text-xs font-bold text-slate-300">
                  {getCategoryIcon(area.category)}
                  <span className="truncate">{area.category}</span>
                </span>
                <span
                  className={`text-[10px] font-extrabold uppercase px-2 py-0.5 rounded-full border ${
                    area.isThreatened
                      ? "bg-red-500/20 text-red-400 border-red-500/40 animate-pulse"
                      : "bg-emerald-500/20 text-emerald-400 border-emerald-500/40"
                  }`}
                >
                  {area.isThreatened ? "THREAT DETECTED" : "NOMINAL"}
                </span>
              </div>

              <h3 className="text-sm font-extrabold text-white tracking-tight mb-1">
                {area.name}
              </h3>
              <p className="text-[11px] text-slate-400">
                Liaison: {area.contactUnit || "Designated District Liaison"}
              </p>
            </div>

            {/* Metrics */}
            <div className="grid grid-cols-2 gap-2 text-xs pt-3 border-t border-slate-800/80">
              <div className="p-2 rounded-lg bg-slate-950 border border-slate-800">
                <span className="text-[10px] uppercase font-bold text-slate-400">Nearest Fire</span>
                <p className="font-mono font-bold text-slate-200 mt-0.5">
                  {area.nearestFireDist ? `${area.nearestFireDist.toFixed(1)} km` : "No Fire"}
                </p>
              </div>

              <div className="p-2 rounded-lg bg-slate-950 border border-slate-800">
                <span className="text-[10px] uppercase font-bold text-slate-400">Smoke ETA</span>
                <p
                  className={`font-mono font-bold mt-0.5 ${
                    area.minEta ? "text-red-400 font-extrabold" : "text-emerald-400"
                  }`}
                >
                  {area.minEta ? `~${Math.round(area.minEta)} min` : "None"}
                </p>
              </div>
            </div>

            {/* Action */}
            {onSelectAreaOnMap && (
              <button
                onClick={() => onSelectAreaOnMap(area.latitude, area.longitude)}
                className="w-full flex items-center justify-center gap-1.5 py-2 px-3 rounded-xl bg-slate-800 hover:bg-slate-700 text-slate-200 text-xs font-bold border border-slate-700 transition-all"
              >
                <MapPin className="w-3.5 h-3.5 text-emerald-400" />
                <span>Locate on Live Map</span>
                <ChevronRight className="w-3.5 h-3.5 text-slate-400" />
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
